-md-4"><label class="form-label" for="crew_effective_date">Effective date *</label><input class="form-control" type="date" id="crew_effective_date" name="crew_effective_date" value="<?=html_escape($value('crew_effective_date'))?>"></div><div class="col-md-10"><label class="form-label" for="crew_notes">Notes</label><input class="form-control" maxlength="500" id="crew_notes" name="crew_notes" value="<?=html_escape($value('crew_notes'))?>"></div><div class="col-md-2 d-flex align-items-end"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="crew_is_benchmark" name="crew_is_benchmark" value="1" <?=$value('crew_is_benchmark')?'checked':''?>><label class="form-check-label" for="crew_is_benchmark">Benchmark</label></div></div></div></div></section>
